// Runtime data loading (JSON files generated by the scripts in tools/).
import { BODY_BY_ID } from './bodies.js';

export async function loadJSON(path) {
  const res = await fetch(path);
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  return res.json();
}

/** Attach the fitted mean elements (data/moons.json) to the moon definitions. */
export function applyMoonOrbits(json) {
  for (const [id, orbit] of Object.entries(json.moons)) if (BODY_BY_ID[id]) BODY_BY_ID[id].orbit = orbit;
}
